import { METRIC_CODES, METRIC_WIDTHS } from './inter_metrics.ts'
import { TYPE, type TypeRole, type TypeSpec } from './tokens.ts'

/**
 * Text measured the way the browser sets it, without a browser: advance widths of the
 * template's four Inter files (generated by scripts/portfolio_metrics.mjs) rounded to whole pixels
 * as Chromium does, letter spacing added to every character, and a greedy wrap at spaces and after hyphens and dashes.
 * The writer's budgets, the fit loop and the composer all use these numbers. Browser-safe.
 */
type FontKey = keyof typeof METRIC_WIDTHS

const INDEX = new Map(METRIC_CODES.map((code, i) => [code, i]))
/** CSS pixels per point. */
const PX = 4 / 3

const fontKey = (spec: Pick<TypeSpec, 'display' | 'weight'>): FontKey =>
  spec.display ? 'display' : (String(spec.weight) as FontKey)

/** Width in points of one line of text (no wrapping, no newline handling). */
export function textWidth(text: string, spec: TypeSpec | TypeRole): number {
  const t: TypeSpec = typeof spec === 'string' ? TYPE[spec] : spec
  const table = METRIC_WIDTHS[fontKey(t)]
  const source = t.caps ? text.toUpperCase() : text
  const px = t.size * PX
  let advance = 0
  let count = 0
  for (const char of source) {
    const i = INDEX.get(char.codePointAt(0)!)
    // Chromium sets each glyph on a whole pixel at these sizes, so the width is the sum of rounded
    // advances (measured: the 7 pt footer is 2.7% wider than its unrounded advances). An unmeasured
    // character is set at the width of an "n".
    advance += Math.round((table[i ?? INDEX.get(110)!] / 1000) * px)
    count++
  }
  return advance / PX + count * (t.tracking ?? 0)
}

/** Words with their trailing break opportunities: a token ends where a line may break. */
function tokens(line: string): string[] {
  const out: string[] = []
  for (const word of line.split(' ')) {
    // A space is attached to the word before it; a hyphen or dash ends a token inside a word.
    const parts = word.split(/(?<=[-–—])(?=[\p{L}\p{N}])/u)
    parts.forEach((part, i) => out.push(i === parts.length - 1 ? `${part} ` : part))
  }
  return out
}

/** Lines of `text` set in `width` points; an explicit newline always breaks. */
export function wrap(text: string, width: number, spec: TypeSpec | TypeRole): string[] {
  const lines: string[] = []
  for (const paragraph of text.split('\n')) {
    let current = ''
    for (const token of tokens(paragraph.trim())) {
      const next = current + token
      // Trailing spaces hang past the edge, as in the browser.
      if (current && textWidth(next.replace(/ $/, ''), spec) > width + 0.01) {
        lines.push(current.replace(/ $/, ''))
        current = token
      } else current = next
    }
    lines.push(current.replace(/ $/, ''))
  }
  return lines
}

export const lineCount = (text: string, width: number, spec: TypeSpec | TypeRole) =>
  text.trim() ? wrap(text, width, spec).length : 0

/** Whether `text` has a line wider than the frame (an unbreakable word): the browser would clip it. */
export const hasOverlongWord = (text: string, width: number, spec: TypeSpec | TypeRole) =>
  text.split(/\s+/).some((word) => textWidth(word, spec) > width)

/**
 * `text` set on at most `maxLines` lines, with the lines broken as evenly as possible
 * (the cover title's "composed" lines). Returns null when it cannot fit.
 */
export function balanceLines(
  text: string,
  width: number,
  spec: TypeSpec | TypeRole,
  maxLines: number
): string[] | null {
  const words = text.trim().split(/\s+/).filter(Boolean)
  const n = words.length
  if (!n) return []
  const w = (i: number, j: number) => textWidth(words.slice(i, j).join(' '), spec)
  // best[k][j]: least squared slack setting the first j words on k lines.
  const best: number[][] = Array.from({ length: maxLines + 1 }, () => Array(n + 1).fill(Infinity))
  const from: number[][] = Array.from({ length: maxLines + 1 }, () => Array(n + 1).fill(0))
  best[0][0] = 0
  for (let k = 1; k <= maxLines; k++)
    for (let j = 1; j <= n; j++)
      for (let i = k - 1; i < j; i++) {
        const lineWidth = w(i, j)
        if (lineWidth > width || best[k - 1][i] === Infinity) continue
        // The last line may be short; the others should be near the full measure.
        const slack = k === maxLines || j === n ? 0 : (width - lineWidth) ** 2
        const cost = best[k - 1][i] + slack
        if (cost < best[k][j]) {
          best[k][j] = cost
          from[k][j] = i
        }
      }
  // Composed titles use every line they are given once they have words enough; shorter text, the fewest.
  const finite = Array.from({ length: maxLines }, (_, k) => k + 1).filter(
    (k) => best[k][n] < Infinity
  )
  if (!finite.length) return null
  const used = n > maxLines ? finite.at(-1)! : finite[0]
  const lines: string[] = []
  let j = n
  for (let k = used; k >= 1; k--) {
    const i = from[k][j]
    lines.unshift(words.slice(i, j).join(' '))
    j = i
  }
  return lines
}

/**
 * `text` cut to fit `maxLines` lines of `width`: at the last sentence that fits, else the last
 * word, never mid-word. Returns the text and whether anything was cut.
 */
export function trimToLines(
  text: string,
  width: number,
  spec: TypeSpec | TypeRole,
  maxLines: number
): { text: string; cut: boolean } {
  if (lineCount(text, width, spec) <= maxLines) return { text, cut: false }
  const sentences = text.split(/(?<=[.!?])\s+/)
  for (let k = sentences.length - 1; k >= 1; k--) {
    const candidate = sentences.slice(0, k).join(' ')
    if (lineCount(candidate, width, spec) <= maxLines) return { text: candidate, cut: true }
  }
  const words = text.split(/\s+/)
  for (let k = words.length - 1; k >= 1; k--) {
    const candidate = `${words
      .slice(0, k)
      .join(' ')
      .replace(/[\s,;:–—-]+$/, '')}.`
    if (lineCount(candidate, width, spec) <= maxLines) return { text: candidate, cut: true }
  }
  return { text: words[0] ?? '', cut: true }
}

/** Characters a line of `width` holds on average for prose in this role: for prompt targets. */
export function charsPerLine(width: number, spec: TypeSpec | TypeRole): number {
  const sample = 'the service team reviewed each request and agreed the next step together'
  return Math.floor((sample.length / textWidth(sample, spec)) * width)
}
